  <script>
    // reveal on scroll
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduced){items.forEach(i=>i.classList.add('visible'));return}
      const io = new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){const el=e.target;setTimeout(()=>el.classList.add('visible'),parseInt(el.getAttribute('data-delay')||0,10));io.unobserve(el);}});},{threshold:0.12});
      items.forEach(i=>io.observe(i));
    })();

    // booking form basic handler (stub)
    (function(){
      const form = document.getElementById('bookingForm');
      form.addEventListener('submit',function(e){
        e.preventDefault();
        const data = new FormData(form);
        // simulate a submission acknowledgement
        alert('Thank you. I will review your request and reply to ' + (data.get('email')||'your email'));
        form.reset();
      });
    })();

    // short exercise modal
    (function(){
      const btn = document.getElementById('tryItBook');
      const modal = document.getElementById('exerciseModal');
      const close = document.getElementById('closeExercise');
      btn.addEventListener('click',()=>{modal.style.display='flex'});
      close.addEventListener('click',()=>{modal.style.display='none'});
      modal.addEventListener('click',(e)=>{if(e.target===modal) modal.style.display='none'});
    })();
  </script>

